package run.halo.starter;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;
import org.springframework.test.web.reactive.server.WebTestClient;
import reactor.core.publisher.Mono;
import run.halo.app.extension.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
class McpEnrollmentTest {
 @Test void newAgentsHaveIndependentCredentialsAndDisconnectDoesNotBreakOthers(){var client=mock(ReactiveExtensionClient.class);var saved=new AtomicReference<Secret>();when(client.fetch(eq(Secret.class),anyString())).thenAnswer(i->Mono.justOrEmpty(saved.get()));when(client.create(any(Secret.class))).thenAnswer(i->{var s=(Secret)i.getArgument(0);s.getMetadata().setVersion(0L);saved.set(s);return Mono.just(s);});when(client.update(any(Secret.class))).thenAnswer(i->{saved.set(i.getArgument(0));return Mono.just(saved.get());});var config=new McpConfigService(client);String old=config.issueMcpToken().block().get("token");var one=config.enrollAgent("Agent One").block();var two=config.enrollAgent("Agent Two").block();assertTrue(config.validMcpToken(old).block());assertTrue(config.validMcpToken(one.get("token")).block());assertTrue(config.validMcpToken(two.get("token")).block());assertEquals(2,config.listAgents().block().size());assertFalse(McpEndpoint.serialize(config.listAgents().block()).contains(one.get("token")));assertFalse(McpConfigService.value(saved.get(),"agents").contains(one.get("token")));config.revokeAgent(one.get("connectionId")).block();assertFalse(config.validMcpToken(one.get("token")).block());assertTrue(config.validMcpToken(two.get("token")).block());assertTrue(config.validMcpToken(old).block());}
 @Test void enrollmentUsesOneTimeCodeNotMiniappCode(){var config=mock(McpConfigService.class);var access=new McpAccess();var settings=new McpSettings();settings.setEnabled(true);when(config.settings()).thenReturn(Mono.just(settings));when(config.enrollAgent("My Agent")).thenReturn(Mono.just(Map.of("token","a".repeat(43),"connectionId","one","headerName","X-Frame-MCP-Token")));var api=WebTestClient.bindToRouterFunction(new McpPublicEndpoint(config,access,mock(McpEndpoint.class)).endpoint()).build();String mini=access.issueCode();api.post().uri("/mcpenrollments").bodyValue(new McpPublicEndpoint.Enrollment(mini,"My Agent")).exchange().expectStatus().isForbidden();String code=access.issueAgentCode();assertNull(access.bind(code));api.post().uri("/mcpenrollments").bodyValue(new McpPublicEndpoint.Enrollment(code,"My Agent")).exchange().expectStatus().isOk().expectBody().jsonPath("$.headerName").isEqualTo("X-Frame-MCP-Token");api.post().uri("/mcpenrollments").bodyValue(new McpPublicEndpoint.Enrollment(code,"My Agent")).exchange().expectStatus().isForbidden();verify(config,times(1)).enrollAgent("My Agent");}
 @Test void disabledServiceDoesNotConsumeEnrollment(){var config=mock(McpConfigService.class);var settings=new McpSettings();when(config.settings()).thenReturn(Mono.just(settings));var access=new McpAccess();String code=access.issueAgentCode();var api=WebTestClient.bindToRouterFunction(new McpPublicEndpoint(config,access,mock(McpEndpoint.class)).endpoint()).build();api.post().uri("/mcpenrollments").bodyValue(new McpPublicEndpoint.Enrollment(code,"My Agent")).exchange().expectStatus().isEqualTo(503);assertTrue(access.consumeAgentCode(code));verify(config,never()).enrollAgent(any());}
}
